-- Ontology release 0.1.0 (https://example.org/kriminalita/ontology/0.1.0)
PRAGMA foreign_keys = ON;

-- https://example.org/kriminalita/ontology#ClearanceState
CREATE TABLE clearance_state (
    iri TEXT NOT NULL UNIQUE,
    code INTEGER PRIMARY KEY,
    label_cs TEXT NOT NULL,
    label_en TEXT,
    definition_en TEXT NOT NULL,
    source_iri TEXT NOT NULL
);

-- https://example.org/kriminalita/ontology#LocationRelevance
CREATE TABLE location_relevance (
    iri TEXT NOT NULL UNIQUE,
    code INTEGER PRIMARY KEY,
    label_cs TEXT NOT NULL,
    label_en TEXT,
    definition_en TEXT NOT NULL,
    source_iri TEXT NOT NULL
);

-- https://example.org/kriminalita/ontology#OffenceRecord
CREATE TABLE offence_record (
    iri TEXT NOT NULL UNIQUE,
    id INTEGER PRIMARY KEY,
    report_datetime TEXT NOT NULL,
    latitude REAL NOT NULL CHECK (latitude >= -90) CHECK (latitude <= 90),
    longitude REAL NOT NULL CHECK (longitude >= -180) CHECK (longitude <= 180),
    municipal_police INTEGER NOT NULL CHECK (municipal_police IN (0, 1)),
    clearance_state_code INTEGER NOT NULL,
    location_relevance_code INTEGER NOT NULL,
    state_as_of TEXT NOT NULL,
    FOREIGN KEY (clearance_state_code) REFERENCES clearance_state(code),
    FOREIGN KEY (location_relevance_code) REFERENCES location_relevance(code)
);

-- https://example.org/kriminalita/ontology#OffenceType
CREATE TABLE offence_type (
    iri TEXT NOT NULL UNIQUE,
    code INTEGER PRIMARY KEY,
    label_cs TEXT NOT NULL,
    label_en TEXT,
    definition_en TEXT,
    source_iri TEXT NOT NULL,
    broader_code INTEGER,
    FOREIGN KEY (broader_code) REFERENCES offence_type(code)
);

-- Transitive closure of http://www.w3.org/2004/02/skos/core#broader (depth 0 = the item itself)
CREATE VIEW offence_type_ancestor AS
WITH RECURSIVE anc(code, ancestor_code, depth) AS (
    SELECT code, code, 0 FROM offence_type
    UNION ALL
    SELECT anc.code, p.broader_code, anc.depth + 1
    FROM anc JOIN offence_type p ON p.code = anc.ancestor_code
    WHERE p.broader_code IS NOT NULL
)
SELECT code, ancestor_code, depth FROM anc;

-- https://example.org/kriminalita/ontology#hasOffenceType (many-valued)
CREATE TABLE offence_record_type (
    offence_record_id INTEGER NOT NULL,
    offence_type_code INTEGER NOT NULL,
    PRIMARY KEY (offence_record_id, offence_type_code),
    FOREIGN KEY (offence_record_id) REFERENCES offence_record(id),
    FOREIGN KEY (offence_type_code) REFERENCES offence_type(code)
) WITHOUT ROWID;
CREATE INDEX offence_record_type_offence_type_code ON offence_record_type(offence_type_code);

-- Index for period questions (the history is continuous over report time)
CREATE INDEX offence_record_report ON offence_record(report_datetime);

-- Technical tables: loader bookkeeping, not part of the domain model (scripts/dictionary.py)
-- A download file of the publisher (monthly pagination) as last read by the loader.
CREATE TABLE source_file (
    name TEXT PRIMARY KEY,
    publisher_updated TEXT NOT NULL,
    loaded_at TEXT NOT NULL,
    records_read INTEGER NOT NULL
);
-- One run of the loader; the latest finished run is the 'as of' date of the whole database.
CREATE TABLE load_run (
    run_id INTEGER PRIMARY KEY,
    started_at TEXT NOT NULL,
    finished_at TEXT,
    year INTEGER NOT NULL,
    records_new INTEGER,
    records_updated INTEGER,
    state_changes INTEGER
);

-- Metadata: which ontology release this schema realises
CREATE TABLE meta_release (
    ontology_version TEXT NOT NULL,
    ontology_version_iri TEXT NOT NULL,
    generated_from TEXT NOT NULL
);
