INSERT INTO meta_column (table_name, column_name, data_element_en, data_element_cs, definition_en, scope_note_en, object_class_iri, object_class, property_iri, property, value_domain, sql_type, cardinality, nullable, key, business_rule_en, source_field, status, ontology_version) VALUES ('offence_record', 'id', 'record id', 'identifikátor záznamu', 'The publisher''s integer identifier of an offence record, stable across the publisher''s download files and refreshes.', '', 'https://example.org/kriminalita/ontology#OffenceRecord', 'offence record', 'http://purl.org/dc/terms/identifier', 'dcterms:identifier', 'xsd:integer', 'INTEGER', '1..1', 'no', 'PK', 'Every offence record has exactly one integer identifier assigned by the publisher.', 'id', 'reused (dcterms)', '0.1.0');
INSERT INTO meta_column (table_name, column_name, data_element_en, data_element_cs, definition_en, scope_note_en, object_class_iri, object_class, property_iri, property, value_domain, sql_type, cardinality, nullable, key, business_rule_en, source_field, status, ontology_version) VALUES ('offence_record', 'report_datetime', 'report date and time', 'datum a čas oznámení', 'A date-time property that gives the date and time, to the minute and with time zone, at which the recorded act was entered into the Police CR register as reported.', 'Not the time of commission. The publisher''s help (napoveda, "Filtrování dle období") states that an act reported on one day but entered into the register the next day appears under the next day. Times of exactly 00:00 may stand for an unknown time of day.', 'https://example.org/kriminalita/ontology#OffenceRecord', 'offence record', 'https://example.org/kriminalita/ontology#reportDateTime', 'report date and time', 'xsd:dateTime; ISO 8601 text, local time with offset where published', 'TEXT', '1..1', 'no', '', 'Every offence record has exactly one report date and time.', 'date', 'draft', '0.1.0');
INSERT INTO meta_column (table_name, column_name, data_element_en, data_element_cs, definition_en, scope_note_en, object_class_iri, object_class, property_iri, property, value_domain, sql_type, cardinality, nullable, key, business_rule_en, source_field, status, ontology_version) VALUES ('offence_record', 'latitude', 'anonymised latitude', 'anonymizovaná zeměpisná šířka', 'A coordinate property that gives the WGS-84 latitude of the centre of the anonymisation polygon into which the recorded location falls.', 'Not the true place of the act. Municipalities are split into Voronoi polygons around K-means cluster centres, and every location is moved to its polygon''s centre; small municipalities form a single polygon. Realises the source field "y"; note that the publisher''s OpenAPI description mislabels x as latitude and y as longitude.', 'https://example.org/kriminalita/ontology#OffenceRecord', 'offence record', 'https://example.org/kriminalita/ontology#anonymisedLatitude', 'anonymised latitude', 'xsd:decimal; from -90 to 90', 'REAL', '1..1', 'no', '', 'Every offence record has exactly one anonymised latitude between -90 and 90 degrees.', 'y', 'archaic', '0.1.0');
INSERT INTO meta_column (table_name, column_name, data_element_en, data_element_cs, definition_en, scope_note_en, object_class_iri, object_class, property_iri, property, value_domain, sql_type, cardinality, nullable, key, business_rule_en, source_field, status, ontology_version) VALUES ('offence_record', 'longitude', 'anonymised longitude', 'anonymizovaná zeměpisná délka', 'A coordinate property that gives the WGS-84 longitude of the centre of the anonymisation polygon into which the recorded location falls.', 'Not the true place of the act; see krim:anonymisedLatitude. Realises the source field "x".', 'https://example.org/kriminalita/ontology#OffenceRecord', 'offence record', 'https://example.org/kriminalita/ontology#anonymisedLongitude', 'anonymised longitude', 'xsd:decimal; from -180 to 180', 'REAL', '1..1', 'no', '', 'Every offence record has exactly one anonymised longitude between -180 and 180 degrees.', 'x', 'archaic', '0.1.0');
INSERT INTO meta_column (table_name, column_name, data_element_en, data_element_cs, definition_en, scope_note_en, object_class_iri, object_class, property_iri, property, value_domain, sql_type, cardinality, nullable, key, business_rule_en, source_field, status, ontology_version) VALUES ('offence_record', 'municipal_police', 'recorded by municipal police', 'evidováno městskou policií', 'A boolean property that states whether an offence record originates from a municipal police force rather than the Police of the Czech Republic.', 'Realises the source field "mp" (městská policie). The publisher''s OpenAPI description (/api/v2/docs.json) splits statistics into "sp" (state police) and "mp" (municipal police) and describes the codelist flag "mp" as "offence class shared with the municipal police". The help pages state that municipal-police offences are being integrated through a dedicated interface.', 'https://example.org/kriminalita/ontology#OffenceRecord', 'offence record', 'https://example.org/kriminalita/ontology#recordedByMunicipalPolice', 'recorded by municipal police', 'xsd:boolean; stored as 1 (true) / 0 (false)', 'INTEGER', '1..1', 'no', '', 'Every offence record states whether it was recorded by the municipal police.', 'mp', 'draft', '0.1.0');
INSERT INTO meta_column (table_name, column_name, data_element_en, data_element_cs, definition_en, scope_note_en, object_class_iri, object_class, property_iri, property, value_domain, sql_type, cardinality, nullable, key, business_rule_en, source_field, status, ontology_version) VALUES ('offence_record', 'clearance_state_code', 'clearance state', 'stav objasnění', 'A relation that assigns its current clearance state to an offence record.', '', 'https://example.org/kriminalita/ontology#OffenceRecord', 'offence record', 'https://example.org/kriminalita/ontology#hasClearanceState', 'has clearance state', 'code from codelist clearance_state (4 values, see appendix)', 'INTEGER', '1..1', 'no', 'FK -> clearance_state(code)', 'Every offence record has exactly one clearance state.', 'state', 'draft', '0.1.0');
INSERT INTO meta_column (table_name, column_name, data_element_en, data_element_cs, definition_en, scope_note_en, object_class_iri, object_class, property_iri, property, value_domain, sql_type, cardinality, nullable, key, business_rule_en, source_field, status, ontology_version) VALUES ('offence_record', 'location_relevance_code', 'location relevance', 'relevance lokality', 'A relation that states what the recorded location of an offence record stands for.', '', 'https://example.org/kriminalita/ontology#OffenceRecord', 'offence record', 'https://example.org/kriminalita/ontology#hasLocationRelevance', 'has location relevance', 'code from codelist location_relevance (6 values, see appendix)', 'INTEGER', '1..1', 'no', 'FK -> location_relevance(code)', 'Every offence record has exactly one location relevance.', 'relevance', 'draft', '0.1.0');
INSERT INTO meta_column (table_name, column_name, data_element_en, data_element_cs, definition_en, scope_note_en, object_class_iri, object_class, property_iri, property, value_domain, sql_type, cardinality, nullable, key, business_rule_en, source_field, status, ontology_version) VALUES ('offence_record', 'state_as_of', 'state as of', 'stav ke dni', 'A date-time property that gives the moment as of which the publisher reported the current state of an offence record (its clearance state, types and location).', 'Observation time, not event time: it says when the state was known, not when the act was reported (krim:reportDateTime). Records are investigated continuously and republished, so a state can change; only the latest observed state is kept, and a clearance rate is meaningful only together with this date. Taken from the publisher''s ''updated'' timestamp of the download that last contained the record.', 'https://example.org/kriminalita/ontology#OffenceRecord', 'offence record', 'https://example.org/kriminalita/ontology#stateAsOf', 'state as of', 'xsd:dateTime; ISO 8601 text, local time with offset where published', 'TEXT', '1..1', 'no', '', 'Every offence record states exactly one moment as of which its current state was reported.', '', 'draft', '0.1.0');
INSERT INTO meta_column (table_name, column_name, data_element_en, data_element_cs, definition_en, scope_note_en, object_class_iri, object_class, property_iri, property, value_domain, sql_type, cardinality, nullable, key, business_rule_en, source_field, status, ontology_version) VALUES ('offence_record_type', 'offence_record_id', 'offence record (owner)', 'vlastník vazby', 'Identifier of the offence record that the link row belongs to.', '', 'https://example.org/kriminalita/ontology#OffenceRecord', 'offence record', 'http://purl.org/dc/terms/identifier', 'dcterms:identifier', 'identifier of a row in offence_record', 'INTEGER', '1..1', 'no', 'PK, FK -> offence_record(id)', 'Every link row belongs to exactly one owner.', 'id', 'generated', '0.1.0');
INSERT INTO meta_column (table_name, column_name, data_element_en, data_element_cs, definition_en, scope_note_en, object_class_iri, object_class, property_iri, property, value_domain, sql_type, cardinality, nullable, key, business_rule_en, source_field, status, ontology_version) VALUES ('offence_record_type', 'offence_type_code', 'offence type', 'třída deliktu', 'A relation that assigns an offence type to an offence record.', 'A record usually has several types: the most specific ones and all their broader types.', 'https://example.org/kriminalita/ontology#OffenceRecord', 'offence record', 'https://example.org/kriminalita/ontology#hasOffenceType', 'has offence type', 'code from codelist offence_type (132 values, see appendix)', 'INTEGER', '1..*', 'no', 'PK, FK -> offence_type(code)', 'Every offence record has at least one offence type.', 'types', 'draft', '0.1.0');
